    (3, "Which manager introduced the sky blue kit and wrote the Sky Blue Song in the 1960s?", ["Jimmy Hill", "Noel Cantwell", "John Sillett", "Bobby Gould"], 0, "Jimmy Hill, later the presenter of Match of the Day. He took them from the third tier to the first."),
    (2, "What was Coventry's home ground from 1899 to 2005?", ["Highfield Road", "The Ricoh Arena", "Butts Park", "Coundon Road"], 0, "Highfield Road, close to the city centre. It is housing now."),
    (3, "Highfield Road became the first ground in England to be what, in 1981?", ["All-seater", "Floodlit", "Covered on all sides", "Artificial turf"], 0, "All-seater. Fans hated it and the terraces came back within a few years."),
    (2, "When Coventry went down in 2001, how many seasons in a row had they spent in the top flight?", ["14", "24", "34", "44"], 2, "34, since 1967. Only a handful of clubs had a longer unbroken run at the time."),
    (2, "What is the current name of the stadium Coventry moved into in 2005?", ["CBS Arena", "Ricoh Arena", "Highfield Road", "Sky Blue Park"], 0, "The CBS Arena, after a sponsor. It opened as the Ricoh Arena."),
    (3, "In 2013-14 Coventry played their home games in which town because of a rent dispute?", ["Northampton", "Leicester", "Birmingham", "Walsall"], 0, "Northampton, 35 miles away. Attendances collapsed and fans protested outside the empty Ricoh."),
    (3, "From 2019 to 2021 Coventry shared a ground with which club?", ["Birmingham City", "Aston Villa", "Leicester City", "Wolves"], 0, "Birmingham City, at St Andrew's. They won promotion to the Championship while playing there."),
    (2, "Which manager took Coventry from League Two to a Championship play-off final?", ["Mark Robins", "Tony Mowbray", "Steven Pressley", "Russell Slade"], 0, "Mark Robins, in charge from 2017 to 2024. He had scored for the club as a player."),
    (3, "Coventry lost the 2023 Championship play-off final on penalties to which club?", ["Luton Town", "Sunderland", "Middlesbrough", "Millwall"], 0, "Luton Town, after a 1-1 draw at Wembley. Luton went up to the Premier League instead."),
    (3, "Coventry's winning goal in the 1987 FA Cup final was an own goal by which Spurs player?", ["Gary Mabbutt", "Chris Waddle", "Glenn Hoddle", "Richard Gough"], 0, "Gary Mabbutt, whose knee deflected a cross into his own net in extra time. A Coventry fanzine was named after the knee."),
