    (2, "Which club is Coventry's main Midlands rival?", ["Birmingham City", "Nottingham Forest", "Derby County", "Stoke City"], 0, "Birmingham City, with Leicester and Aston Villa not far behind in the dislike rankings."),
    (3, "Which striker shared the Premier League Golden Boot in 1998 with 18 goals for Coventry?", ["Dion Dublin", "Darren Huckerby", "Robbie Keane", "Peter Ndlovu"], 0, "Dion Dublin, level with Michael Owen and Chris Sutton. He later became a TV presenter."),
    (3, "Which former England midfielder was appointed Coventry manager in November 2024?", ["Frank Lampard", "Steven Gerrard", "Wayne Rooney", "Scott Parker"], 0, "Frank Lampard, his first job since a difficult spell back at Chelsea."),
    (3, "The Sky Blue Song is sung to the tune of what?", ["The Eton Boating Song", "Jerusalem", "Rule Britannia", "Land of Hope and Glory"], 0, "The Eton Boating Song. Jimmy Hill wrote the words with the club secretary in 1962."),
    (2, "In which division were Coventry playing in 2017-18, the season before their climb began?", ["The Championship", "League One", "League Two", "The National League"], 2, "League Two, the fourth tier, the lowest the club had ever been. They won the play-offs that May."),
