    (2, "Who is Everton's all-time record goalscorer?", ["Dixie Dean", "Graeme Sharp", "Romelu Lukaku", "Bob Latchford"], 0, "Dixie Dean, 383 goals in the 1920s and 30s. There is a statue of him outside Goodison."),
    (3, "How many league goals did Dixie Dean score in the 1927-28 season, still a record?", ["40", "50", "60", "70"], 2, "Sixty, in 39 games. He got the last three in the final match to break the record."),
