    (2, "Who managed Everton through their 1980s glory years?", ["Howard Kendall", "Harry Catterick", "Joe Royle", "Colin Harvey"], 0, "Howard Kendall, two league titles, an FA Cup and a European trophy in three seasons."),
    (2, "Which European trophy did Everton win in 1985?", ["The Cup Winners' Cup", "The European Cup", "The UEFA Cup", "The Super Cup"], 0, "The Cup Winners' Cup, beating Rapid Vienna 3-1 in Rotterdam. Then English clubs were banned from Europe."),
    (2, "In which year did Everton win their last major trophy, the FA Cup?", ["1984", "1995", "2004", "2009"], 1, "1995, beating Manchester United 1-0 at Wembley. Paul Rideout scored."),
    (2, "Wayne Rooney made his first-team debut for which club?", ["Everton", "Manchester United", "Liverpool", "Derby"], 0, "Everton, aged sixteen. His first goal, against Arsenal, ended a 30-game unbeaten run."),
    (2, "Which Scottish manager had two spells at Everton, from 2002 to 2013 and again from 2025?", ["David Moyes", "Walter Smith", "Alex Ferguson", "Gordon Strachan"], 0, "David Moyes. He called Everton the People's Club on his first day and it stuck."),
    (3, "Which club has spent more seasons in England's top division than any other?", ["Everton", "Arsenal", "Liverpool", "Manchester United"], 0, "Everton, relegated only twice in their history, most recently in 1951."),
